(function(){'use strict';
const UI_KEY='nawaf-hq-ui-v21';
const $=s=>document.querySelector(s);
const icons={
 dashboard:'<svg viewBox="0 0 24 24"><path d="M4 4h6v6H4zM14 4h6v10h-6zM4 14h6v6H4zM14 18h6v2h-6z"/></svg>',
 workforce:'<svg viewBox="0 0 24 24"><path d="M16 20v-1.5a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4V20M9 10.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM17 11v6m3-3h-6"/></svg>',
 projects:'<svg viewBox="0 0 24 24"><path d="M3 6.5h6l2 2h10v10H3zM3 6.5v-2h7l2 2"/></svg>',
 tasks:'<svg viewBox="0 0 24 24"><path d="m4 7 2 2 4-4M13 7h7M4 14l2 2 4-4M13 14h7M4 21l2-2 2 2M13 20h7"/></svg>',
 reports:'<svg viewBox="0 0 24 24"><path d="M5 3h14v18H5zM9 16v-3m3 3V8m3 8v-5"/></svg>',
 settings:'<svg viewBox="0 0 24 24"><path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Z"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V21h-4v-.08A1.7 1.7 0 0 0 9 19.37a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.63 15 1.7 1.7 0 0 0 3.08 14H3v-4h.08A1.7 1.7 0 0 0 4.63 9a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 9 4.63 1.7 1.7 0 0 0 10 3.08V3h4v.08A1.7 1.7 0 0 0 15 4.63a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 19.37 9 1.7 1.7 0 0 0 20.92 10H21v4h-.08A1.7 1.7 0 0 0 19.4 15Z"/></svg>',
 command:'<svg viewBox="0 0 24 24"><path d="m12 3 1.4 4.6L18 9l-4.6 1.4L12 15l-1.4-4.6L6 9l4.6-1.4L12 3Zm7 12 .8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8L19 15Z"/></svg>',
 plus:'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>',
 sync:'<svg viewBox="0 0 24 24"><path d="M20 7h-5V2M4 17h5v5M19 12a7 7 0 0 0-12-5l-3 3m1 2a7 7 0 0 0 12 5l3-3"/></svg>'
};
const defaults={background:'mountain',accent:'blue',motion:true,density:'comfortable',contrast:'glass'};
function readPrefs(){try{return {...defaults,...JSON.parse(localStorage.getItem(UI_KEY)||'{}')}}catch{return {...defaults}}}
function savePrefs(p){localStorage.setItem(UI_KEY,JSON.stringify(p));applyPrefs(p)}
function applyPrefs(p=readPrefs()){const r=document.documentElement;r.dataset.v21Background=p.background;r.dataset.v21Accent=p.accent;r.dataset.v21Motion=p.motion?'on':'off';r.dataset.v21Density=p.density;r.dataset.v21Contrast=p.contrast}
function icon(name){return `<i class="v21-icon">${icons[name]||''}</i>`}
function nav(){const n=$('.v8-side nav');if(!n)return;const labels={dashboard:'الرئيسية',workforce:'الفريق',projects:'المشاريع',tasks:'المهام',reports:'التقارير'};n.querySelectorAll('[data-view]').forEach(b=>{const id=b.dataset.view;if(labels[id])b.innerHTML=`${icon(id)}<span>${labels[id]}</span>`});let s=n.querySelector('[data-v21-settings]');if(!s){s=document.createElement('button');s.type='button';s.dataset.v21Settings='';s.innerHTML=`${icon('settings')}<span>الإعدادات</span>`;n.appendChild(s)}s.classList.toggle('active',document.body.classList.contains('v21-settings-open'))}
function actions(){document.querySelectorAll('.v8-actions [data-action="new-employee"]').forEach(b=>{if(!b.querySelector('.v21-icon'))b.innerHTML=`${icon('plus')}<span>موظف</span>`});document.querySelectorAll('.v8-actions [data-action="company-command"]').forEach(b=>{if(!b.querySelector('.v21-icon'))b.innerHTML=`${icon('command')}<span>توجيه الشركة</span>`})}
function backdrop(){if(!$('.v21-atmosphere')){const d=document.createElement('div');d.className='v21-atmosphere';d.setAttribute('aria-hidden','true');d.innerHTML='<span></span><span></span>';document.body.prepend(d)}}
function settingCard(id,title,sub,body){return `<section class="v21-settings-card" id="${id}"><header><div><h2>${title}</h2><p>${sub}</p></div></header>${body}</section>`}
function settings(){const main=$('.v8-main');if(!main)return;const p=readPrefs(),cloud=window.HQCloud?.status?.()||{},engine=!!(window.NawafAgents||window.NawafProjectExecutor);document.body.classList.add('v21-settings-open');document.querySelectorAll('.v8-side [data-view]').forEach(b=>b.classList.remove('active'));main.innerHTML=`<header class="v21-settings-head"><div><span>WORKSPACE</span><h1>إعدادات مساحة العمل</h1><p>خصص الأجواء وكثافة العرض وحركة الخلفية بدون التأثير على بيانات الشركة.</p></div><button data-v21-close-settings>العودة للرئيسية</button></header><div class="v21-settings-grid">${settingCard('appearance','الخلفية والأجواء','اختر المشهد الذي يناسب تركيزك. الحركة هادئة وخفيفة.','<div class="v21-scenes">'+[['mountain','قمم الليل','تركيز وهدوء'],['ocean','الساحل','حركة واتساع'],['desert','الرؤية','دفء سعودي معاصر']].map(([id,name,sub])=>`<button data-v21-scene="${id}" class="${p.background===id?'selected':''}"><span></span><b>${name}</b><small>${sub}</small><i>✓</i></button>`).join('')+'</div>')}${settingCard('interface','الواجهة','تحكم فعلي في الشكل والراحة البصرية.',`<div class="v21-control-list"><label><span><b>حركة الخلفية</b><small>حركة سينمائية بطيئة وخفيفة</small></span><input type="checkbox" data-v21-motion ${p.motion?'checked':''}><i></i></label><label><span><b>كثافة الواجهة</b><small>المسافات وحجم العناصر</small></span><select data-v21-density><option value="comfortable" ${p.density==='comfortable'?'selected':''}>مريحة</option><option value="compact" ${p.density==='compact'?'selected':''}>مضغوطة</option></select></label><label><span><b>وضوح الأسطح</b><small>توازن الصورة مع المحتوى</small></span><select data-v21-contrast><option value="glass" ${p.contrast==='glass'?'selected':''}>زجاجي</option><option value="solid" ${p.contrast==='solid'?'selected':''}>أوضح</option></select></label></div><div class="v21-accent"><b>لون التركيز</b>${[['blue','أزرق'],['bronze','برونزي'],['violet','بنفسجي']].map(([id,n])=>`<button data-v21-accent="${id}" class="${p.accent===id?'selected':''}"><i></i>${n}</button>`).join('')}</div>`) }${settingCard('system','النظام والمزامنة','حالة حقيقية من الخدمات المحمّلة الآن.',`<div class="v21-health"><div><i class="${engine?'ok':'warn'}"></i><span><b>محرك التنفيذ</b><small>${engine?'جاهز لاستقبال المهام':'يحتاج تحقق'}</small></span><strong>${engine?'متصل':'تحقق'}</strong></div><div><i class="${cloud.cloud!==false?'ok':'warn'}"></i><span><b>المزامنة السحابية</b><small>${cloud.dirty?'تغييرات تنتظر الحفظ':'الحالة متزامنة'}</small></span><strong>${cloud.dirty?'معلقة':'متصل'}</strong></div><div><i class="ok"></i><span><b>واجهة الشركة</b><small>NAWAF HQ Modern Workspace</small></span><strong>V21</strong></div></div><div class="v21-settings-actions"><button data-v21-sync>${icon('sync')}مزامنة الآن</button><button class="quiet" data-v21-reset>إعادة ضبط المظهر</button></div>`)}</div>`;bindSettings();nav()}
function bindSettings(){document.querySelectorAll('[data-v21-scene]').forEach(b=>b.onclick=()=>{const p=readPrefs();p.background=b.dataset.v21Scene;savePrefs(p);settings()});document.querySelectorAll('[data-v21-accent]').forEach(b=>b.onclick=()=>{const p=readPrefs();p.accent=b.dataset.v21Accent;savePrefs(p);settings()});$('[data-v21-motion]')?.addEventListener('change',e=>{const p=readPrefs();p.motion=e.target.checked;savePrefs(p)});$('[data-v21-density]')?.addEventListener('change',e=>{const p=readPrefs();p.density=e.target.value;savePrefs(p)});$('[data-v21-contrast]')?.addEventListener('change',e=>{const p=readPrefs();p.contrast=e.target.value;savePrefs(p)});$('[data-v21-sync]')?.addEventListener('click',async()=>{const b=$('[data-v21-sync]');b.disabled=true;b.textContent='جاري المزامنة…';try{await window.HQCloud?.pull?.();b.textContent='تمت المزامنة ✓'}catch{b.textContent='تعذرت المزامنة'}setTimeout(()=>settings(),900)});$('[data-v21-reset]')?.addEventListener('click',()=>{savePrefs({...defaults});settings()});$('[data-v21-close-settings]')?.addEventListener('click',()=>document.querySelector('[data-view="dashboard"]')?.click())}
function enhance(){backdrop();if(!document.body.classList.contains('v21-settings-open')){nav();actions()}else nav();document.body.classList.add('v21-ready')}
document.addEventListener('click',e=>{if(e.target.closest('[data-v21-settings]')){e.preventDefault();settings();return}if(e.target.closest('[data-view]')){document.body.classList.remove('v21-settings-open');setTimeout(enhance,140)}});
window.addEventListener('nawaf:state-updated',()=>setTimeout(enhance,160));
function boot(){applyPrefs();enhance();setTimeout(enhance,220)}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
window.NawafHQV21={settings,applyPrefs};
})();
